class ListNode:
    def __init__(self, value=0, next=None):
        self.value = value
        self.next = next

def build_list(values):
    head = None
    tail = None
    for value in values:
        node = ListNode(value)
        if head is None:
            head = tail = node
        else:
            tail.next = node
            tail = node
    return head

def unlink_chain(node):
    while node is not None:
        following = node.next
        node.next = None
        node = following

def to_values(head):
    values = []
    while head is not None:
        values.append(head.value)
        following = head.next
        head.next = None
        head = following
    return values

def prepare(raw):
    head = build_list(raw[0])
    def finish(result):
        values = to_values(result)
        unlink_chain(head)
        return values
    return [head, raw[1]], finish
